            copy.add(clip);
        }
        return new Console(copy);
    }

    public static List<Clip> search(Console console, String term) {
        requireConsole(console);
        if (term == null) throw new IllegalArgumentException("term must not be null");
        String target = term.trim();
        List<Clip> matches = new ArrayList<Clip>();
        for (Clip clip : console.catalog) {
            if (clip.title.contains(target)
                    || clip.creator.contains(target)) matches.add(clip);
        }
        return Collections.unmodifiableList(matches);
    }

    public static int getLevel(Console console) {
        requireConsole(console);
        return console.level;
    }

