import java.util.ArrayList;
import java.util.Arrays;
import java.util.List;

public class SolutionTest {
    public static void main(String[] args) {
        Solution.Clip one = new Solution.Clip(" 1 ", "  Morning News ", " Alice ");
        Solution.Clip two = new Solution.Clip("2", "Evening Show", "BOB");
        Solution.Clip three = new Solution.Clip("3", "Alice in Space", "Carol");
        eq("1", one.getId());
        eq("Morning News", one.getTitle());
        eq("Alice", one.getCreator());

        List<Solution.Clip> catalog = new ArrayList<Solution.Clip>(Arrays.asList(one, two, three));
        Solution.Console console = Solution.createConsole(catalog);
        catalog.clear();
        eq(50, Solution.getLevel(console));
        no(Solution.isActive(console));

        List<Solution.Clip> alice = Solution.search(console, "  aLiCe ");
        eq(2, alice.size());
        same(one, alice.get(0));
        same(three, alice.get(1));
        List<Solution.Clip> all = Solution.search(console, "  ");
        eq(3, all.size());
        immutable(all);
        eq(0, Solution.search(console, "missing").size());

        Solution.setLevel(console, 0);
        eq(0, Solution.getLevel(console));
        Solution.setLevel(console, 100);
        eq(100, Solution.getLevel(console));
        bad(() -> Solution.setLevel(console, -1));
        bad(() -> Solution.setLevel(console, 101));

        no(Solution.select(console, "missing"));
        no(Solution.isActive(console));
        ok(Solution.select(console, "2"));
        ok(Solution.isActive(console));
        no(Solution.select(console, "missing"));
        ok(Solution.isActive(console));

        Solution.Console empty = Solution.createConsole(new ArrayList<Solution.Clip>());
        eq(0, Solution.search(empty, "").size());
        eq(50, Solution.getLevel(empty));
        no(Solution.isActive(empty));

        bad(() -> new Solution.Clip(null, "t", "c"));
        bad(() -> new Solution.Clip(" ", "t", "c"));
        bad(() -> new Solution.Clip("i", "\t", "c"));
        bad(() -> new Solution.Clip("i", "t", null));
        bad(() -> Solution.createConsole(null));
        bad(() -> Solution.createConsole(Arrays.asList(one, null)));
        bad(() -> Solution.createConsole(Arrays.asList(one, new Solution.Clip("1", "Other", "Other"))));
        bad(() -> Solution.search(null, "x"));
        bad(() -> Solution.search(console, null));
        bad(() -> Solution.getLevel(null));
        bad(() -> Solution.setLevel(null, 50));
        bad(() -> Solution.select(null, "1"));
        bad(() -> Solution.select(console, null));
        bad(() -> Solution.isActive(null));
    }

    private static void immutable(List<Solution.Clip> list) {
        try { list.clear(); fail(); } catch (UnsupportedOperationException expected) {}
    }
    private static void bad(Runnable r) {
        try { r.run(); fail(); } catch (IllegalArgumentException expected) {}
    }
    private static void ok(boolean v) { if (!v) fail(); }
    private static void no(boolean v) { if (v) fail(); }
    private static void same(Object a, Object b) { if (a != b) fail(); }
    private static void eq(Object a, Object b) { if (a == null ? b != null : !a.equals(b)) fail(); }
    private static void fail() { throw new AssertionError(); }
}

